+                // The cell an item is moved to when dropped at x, y with the given
+                // cursor offset, or null when that is past the end of a stripe.
+                function dropTargetIndex(x, y, offset) {
+                    const rows = (flow === GridView.FlowLeftToRight);
+                    const dropPos = mapToItem(contentItem, x, y);
+
+                    // The +(cellWidth / 2) is kept here to make it easier to drag items between cells.
+                    let itemX = dropPos.x + offset.x + (cellWidth / 2);
+                    const itemY = dropPos.y + offset.y + verticalDropHitscanOffset;
+
+                    if (effectiveLayoutDirection === Qt.RightToLeft) {
+                        itemX -= (rows ? contentX : originX);
+                        itemX = (rows ? width : contentItem.width) - itemX;
+                    }
+
+                    let col = rows ? Math.floor(itemX / cellWidth) : Math.floor(itemY / cellHeight);
+                    const row = rows ? Math.floor(itemY / cellHeight) : Math.floor(itemX / cellWidth);
+
+                    if (col > positioner.perStripe) {
+                        return null;
+                    }
+
+                    // We have somehow moved the item outside of the available
+                    // areas (usually during file creation), so make sure
+                    // the col is within perStripe
+                    if (col === positioner.perStripe) {
+                        col -= 1;
+                    }
+
+                    return (row * positioner.perStripe) + col;
+                }
+
+                // Where items aimed at the target cells end up: like Positioner::move(),
+                // an item aimed at a taken cell goes to the next free one.
+                function landingCells(targets, movedRows) {
+                    if (targets.some(target => target < 0)) {
+                        return [];
+                    }
+
+                    let cells = [];
+                    for (let cell of targets) {
+                        while ((!movedRows.includes(cell) && !positioner.isBlank(cell)) || cells.includes(cell)) {
+                            ++cell;
+                        }
+                        cells.push(cell);
+                    }
+                    return cells;
+                }
+
+                function cellRect(index) {
+                    const rows = (flow === GridView.FlowLeftToRight);
+                    const stripe = Math.floor(index / positioner.perStripe);
+                    const col = index % positioner.perStripe;
+                    let x = (rows ? col : stripe) * cellWidth;
+                    const y = (rows ? stripe : col) * cellHeight;
+
+                    if (effectiveLayoutDirection === Qt.RightToLeft) {
+                        x = (rows ? width + contentX : contentItem.width + originX) - x - cellWidth;
+                    }
+
+                    return Qt.rect(x, y, cellWidth, cellHeight);
+                }
+
+                Repeater {
+                    parent: gridView.contentItem
+                    model: {
+                        let cells = main.dropTargetCells;
+                        const newItemPos = dir.newItemPosition;
+                        if (positioner.enabled && newItemPos.x >= 0) {
+                            const target = gridView.dropTargetIndex(newItemPos.x, newItemPos.y, Qt.point(0, 0));
+                            if (target !== null) {
+                                cells = cells.concat(gridView.landingCells([target], []));
+                            }
+                        }
+                        return cells;
+                    }
+
+                    KSvg.FrameSvgItem {
+                        required property int modelData
+                        readonly property rect cell: gridView.cellRect(modelData)
+
+                        x: cell.x + Kirigami.Units.smallSpacing
+                        y: cell.y + Kirigami.Units.smallSpacing
+                        z: -1
+                        width: cell.width - (Kirigami.Units.smallSpacing * 2)
+                        height: Math.min(cell.height, gridView.iconSize + (Kirigami.Units.gridUnit * Plasmoid.configuration.textLines) + (Kirigami.Units.smallSpacing * 3)) - (Kirigami.Units.smallSpacing * 2)
+
+                        imagePath: "widgets/viewitem"
+                        prefix: "hover"
+                    }
+                }
+
                 PlasmaComponents.ScrollBar.vertical: PlasmaComponents.ScrollBar {
                     id: verticalScrollBar
                 }
